                new_grid = grid.copy()
                for di in range(2):
                    for dj in range(2):
                        new_grid[m+di, l+dj] = 1 - new_grid[m+di, l+dj]
                for i in range(n-1):
                    for j in range(n-1):
                        s_new = new_grid[i,j] + new_grid[i+1,j] + new_grid[i,j+1] + new_grid[i+1,j+1]
                        if s_new == 3:
                            return False
    return True

